"use client";

import manifest from "./image-manifest.json";

type LoaderArgs = { src: string; width: number; quality?: number };

/**
 * Global next/image loader (images.loaderFile).
 * - Sanity / Unsplash images: resized by their own CDN (w/q/auto=format), no proxy hop.
 * - Local images listed in image-manifest.json: pre-resized WebP variants in /public/_opt
 *   (generated by `npm run images`), picking the smallest variant >= the requested width.
 * - Everything else (files in /public): served directly from /public.
 */
export default function imageLoader({ src, width, quality }: LoaderArgs) {
  // Sanity and Unsplash CDNs both resize via the same w/q/auto=format params.
  if (src.startsWith("https://cdn.sanity.io/") || src.startsWith("https://images.unsplash.com/")) {
    const url = new URL(src);
    url.searchParams.set("w", String(width));
    url.searchParams.set("q", String(quality || 75));
    url.searchParams.set("auto", "format");
    return url.toString();
  }
  const widths = (manifest as Record<string, number[]>)[src];
  if (widths) {
    const w = widths.find((v) => v >= width) ?? widths[widths.length - 1];
    const base = src.slice(src.lastIndexOf("/") + 1, src.lastIndexOf("."));
    return `/_opt/${base}-${w}.webp`;
  }
  // A custom loader disables Next's /_next/image endpoint, so local files are served as-is
  // (the width param is ignored by the static file server but keeps srcset entries distinct).
  return `${src}?w=${width}`;
}
